        sampler.addAndMakeVisible(sampleKeyboard);sampler.addAndMakeVisible(wave);wave.setTooltip("Drag the nearest trim edge. Shift-click adds a slice; right-click removes the nearest slice.");wave.onMarker=[this](double point,bool remove){if(!wave.asset)return;owner.checkpoint();auto& settings=selected().sampler;if(remove&&settings.sliceCount>0){auto first=settings.slices.begin(),last=first+settings.sliceCount;auto it=std::min_element(first,last,[point](double a,double b){return std::abs(a-point)<std::abs(b-point);});std::move(it+1,last,it);--settings.sliceCount;}else if(!remove&&settings.sliceCount<128-settings.sliceBase){settings.slices[(size_t)settings.sliceCount++]=settings.snap?snapSamplePoint(*wave.asset,point):point;}settings.mode=2;commit();};wave.onGesture=[this]{owner.checkpoint();};wave.onRegion=[this](double a,double b){auto& s=selected().sampler;s.start=std::min(a,b-.000001);s.end=std::max(b,a+.000001);s.normalise();commit();};
