        button(sampler,"DETECT SLICES",[this]{auto asset=owner.audio.sampleAsset(track);if(!asset)return;owner.checkpoint();auto& s=selected().sampler;auto points=detectSampleSlices(*asset,s.start,s.end,s.sensitivity,128-s.sliceBase);s.sliceCount=(int)points.size();std::fill(s.slices.begin(),s.slices.end(),0);std::copy(points.begin(),points.end(),s.slices.begin());s.mode=2;commit();});
        button(sampler,"WRITE SLICE MIDI",[this]{auto asset=owner.audio.sampleAsset(track);if(!asset||selected().locked)return;auto& s=selected().sampler;if(!s.sliceCount)return;owner.select(track,owner.selectedSection);owner.ensureTimelineClip();if(owner.clip().locked)return;owner.checkpoint();auto& c=owner.clip();c.notes.clear();c.loopSource.clear();c.loopLength=0;s.mode=2;for(int i=0;i<s.sliceCount;++i){double at=(s.slices[(size_t)i]-s.start)*asset->seconds()*s.sourceBpm/60.;if(at>=owner.clipLength())break;c.notes.push_back({at,std::min(.125,owner.clipLength()-at),s.sliceBase+i,100,0});}owner.changed(true,track);owner.piano.fitNotes();owner.updateSizes();refresh();});
        sampler.addAndMakeVisible(zoom);zoom.setRange(1,32,.1);zoom.setValue(1);zoom.onValueChange=[this]{wave.zoom=zoom.getValue();wave.scroll=std::min(wave.scroll,1.-1./wave.zoom);wave.repaint();};Localisation::bindTip(zoom,"Waveform zoom");
